// CreateTable creates the Purchase_Header table for the specified company (SQLite)
// The db parameter can be either *sql.DB or *sql.Tx
func (t *PurchaseHeader) CreateTable(db database.Executor, company string) error {
	return t.CreateTableWithDBType(db, company, database.DBTypeSQLite)
}

// CreateTableWithDBType creates the Purchase_Header table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *PurchaseHeader) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, PurchaseHeaderTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetPurchaseHeaderPostgresTableSchema()
	} else {
		schema = GetPurchaseHeaderTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create Purchase_Header table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *PurchaseHeader) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, PurchaseHeaderTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (document_type, no)`,
		fmt.Sprintf("%s$Purchase_Header$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (document_type, buy_from_vendor_no)`,
		fmt.Sprintf("%s$Purchase_Header$vendor", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index vendor: %w", err)
	}
	var keys []sift.Key
	for _, spec := range purchaseHeaderSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, PurchaseHeaderTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, PurchaseHeaderTableName, keys)
}

// purchaseHeaderSIFTSpecs are the table's keys with sum_index_fields
func purchaseHeaderSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *PurchaseHeader) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, PurchaseHeaderTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range purchaseHeaderSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, PurchaseHeaderTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: PurchaseHeaderTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, PurchaseHeaderTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

