// SetDB changes the database executor of the record without touching its values — e.g. to
// run a Modify (with its rename cascade) inside a transaction.
func (t *PurchaseHeader) SetDB(db database.Executor) {
	t.db = db
}

// renameReferences carries a renamed key over to every field of another table that refers
// to it (Rename). References from company tables are updated in this company — in
// every company when this table is global. Runs on the record's executor, so inside the
// caller's transaction.
func (t *PurchaseHeader) renameReferences(field string, oldValue, newValue interface{}) error {
	type reference struct {
		table      string
		global     bool
		column     string
		condColumn string // a conditional relation: only rows whose condColumn = condValue
		condValue  int
	}
	references := map[string][]reference{
		"no": {{"Purch_Cr_Memo_Line", false, "blanket_order_no", "", 0}, {"Purch_Inv_Line", false, "blanket_order_no", "", 0}, {"Purch_Rcpt_Line", false, "blanket_order_no", "", 0}, {"Purchase_Line", false, "blanket_order_no", "", 0}, {"Sales_Line", false, "purchase_order_no", "", 0}},
	}
	companies := []string{t.company}
	for _, ref := range references[field] {
		tables := []string{ref.table}
		if !ref.global {
			tables = tables[:0]
			for _, c := range companies {
				tables = append(tables, c+"$"+ref.table)
			}
		}
		for _, tbl := range tables {
			stmt := fmt.Sprintf(`UPDATE "%s" SET %s = ? WHERE %s = ?`, tbl, ref.column, ref.column)
			args := []interface{}{newValue, oldValue}
			if ref.condColumn != "" {
				stmt += fmt.Sprintf(" AND %s = ?", ref.condColumn)
				args = append(args, ref.condValue)
			}
			query := t.convertPlaceholders(stmt, len(args))
			if _, err := t.db.Exec(query, args...); err != nil {
				return fmt.Errorf("%s.%s: %w", tbl, ref.column, err)
			}
		}
	}
	return nil
}

// Delete removes the record from the database
func (t *PurchaseHeader) Delete(runTrigger bool) bool {
	// OnDelete trigger of the business logic
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnDelete(); err != nil {
			fmt.Printf("Error: OnDelete trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, PurchaseHeaderTableName)

	// Collect arguments for DELETE
	args := []interface{}{
		t.Document_type,
		t.No,
	}

	// Build SQL with placeholders
	sqlStr := fmt.Sprintf(`DELETE FROM "%s" WHERE 1=1 AND document_type = ? AND no = ?`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	_, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to delete Purchase_Header: %v\n", err)
		return false
	}
	return true
}

// ========================================
// FlowField Calculations
// ========================================

// CalcFields calculates FlowField values
// Usage:
//
//	customer.CalcFields("balance", "balance_lcy") - Calculate specific fields
//	customer.CalcFields() - Calculate all FlowFields
func (t *PurchaseHeader) CalcFields(fieldNames ...string) {
	// If no field names specified, calculate all FlowFields
	if len(fieldNames) == 0 {
		t.calcFlowField_comment()
		t.calcFlowField_amount()
		t.calcFlowField_amount_including_tax()
		return
	}

	// Calculate only specified fields
	for _, fieldName := range fieldNames {
		switch fieldName {
		case "comment":
			t.calcFlowField_comment()
		case "amount":
			t.calcFlowField_amount()
		case "amount_including_tax":
			t.calcFlowField_amount_including_tax()
		}
	}
}

// calcFlowField_comment calculates the comment FlowField
// CalcFormula: Exist(PurchCommentLine.line_no)
func (t *PurchaseHeader) calcFlowField_comment() {
	t.Comment = t.calcCount_comment() > 0
}

// calcFlowField_amount calculates the amount FlowField
// CalcFormula: Sum(PurchaseLine.amount)
func (t *PurchaseHeader) calcFlowField_amount() {
	t.Amount = t.calcSum_amount()
}

// calcFlowField_amount_including_tax calculates the amount_including_tax FlowField
// CalcFormula: Sum(PurchaseLine.amount_including_tax)
func (t *PurchaseHeader) calcFlowField_amount_including_tax() {
	t.Amount_including_tax = t.calcSum_amount_including_tax()
}

// CalcFieldsForRecords calculates FlowFields for many records at once (list pages):
// one grouped query per FlowField instead of one query per record. records are
// ToMap() results; each gets its FlowField values under the field name. With no
// field names, all FlowFields are calculated.
func (t *PurchaseHeader) CalcFieldsForRecords(records []map[string]interface{}, fieldNames ...string) {
	if len(records) == 0 {
		return
	}
	if len(fieldNames) == 0 {
		fieldNames = t.GetFlowFields()
	}
	for _, fieldName := range fieldNames {
		switch fieldName {
		case "comment":
			t.calcForRecords_comment(records)
		case "amount":
			t.calcForRecords_amount(records)
		case "amount_including_tax":
			t.calcForRecords_amount_including_tax(records)
		}
	}
}

// calcForRecords_comment calculates the comment FlowField for a set of records
// CalcFormula: Exist(PurchCommentLine.line_no)
func (t *PurchaseHeader) calcForRecords_comment(records []map[string]interface{}) {
	// No single key field to group by: calculate per record, with this record's FlowFilters
	for _, rec := range records {
		r := &PurchaseHeader{db: t.db, company: t.company, dbType: t.dbType}
		r.FromMap(rec)
		r.calcFlowField_comment()
		rec["comment"] = r.Comment
	}
}

// calcForRecords_amount calculates the amount FlowField for a set of records
// CalcFormula: Sum(PurchaseLine.amount)
func (t *PurchaseHeader) calcForRecords_amount(records []map[string]interface{}) {
	// No single key field to group by: calculate per record, with this record's FlowFilters
	for _, rec := range records {
		r := &PurchaseHeader{db: t.db, company: t.company, dbType: t.dbType}
		r.FromMap(rec)
		r.calcFlowField_amount()
		rec["amount"] = r.Amount.String()
	}
}

// calcForRecords_amount_including_tax calculates the amount_including_tax FlowField for a set of records
// CalcFormula: Sum(PurchaseLine.amount_including_tax)
func (t *PurchaseHeader) calcForRecords_amount_including_tax(records []map[string]interface{}) {
	// No single key field to group by: calculate per record, with this record's FlowFilters
	for _, rec := range records {
		r := &PurchaseHeader{db: t.db, company: t.company, dbType: t.dbType}
		r.FromMap(rec)
		r.calcFlowField_amount_including_tax()
		rec["amount_including_tax"] = r.Amount_including_tax.String()
	}
}

// Helper methods for FlowField calculations

func (t *PurchaseHeader) calcCount_comment() int {
	// Source: the SIFT totals table of a key covering the filters, else the entries
	tableName, useSIFT := fmt.Sprintf("%s$%s", t.company, PurchCommentLineTableName), false
	_ = useSIFT

	// Build WHERE clause from FlowFilters
	var whereClauses []string
	var args []interface{}
	whereClauses = append(whereClauses, "document_type = ?")
	args = append(args, t.Document_type)
	whereClauses = append(whereClauses, "no = ?")
	args = append(args, t.No)

	whereClause := "1=1"
	if len(whereClauses) > 0 {
		whereClause = strings.Join(whereClauses, " AND ")
	}

	agg := "COUNT(*)"
	if useSIFT {
		agg = "COALESCE(SUM(cnt), 0)" // the totals hold the entry count per key value
	}
	query := fmt.Sprintf(`SELECT %s FROM "%s" WHERE %s`, agg, tableName, whereClause)

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))

	var count int
	err := t.db.QueryRow(query, args...).Scan(&count)
	if err != nil {
		fmt.Printf("Error: Failed to calculate count for comment: %v\n", err)
		return 0
	}

	return count
}

func (t *PurchaseHeader) calcSum_amount() types.Decimal {
	// Source: the SIFT totals table of a key covering the filters, else the entries
	tableName, useSIFT := fmt.Sprintf("%s$%s", t.company, PurchaseLineTableName), false
	_ = useSIFT

	// Build WHERE clause from FlowFilters
	var whereClauses []string
	var args []interface{}
	whereClauses = append(whereClauses, "document_type = ?")
	args = append(args, t.Document_type)
	whereClauses = append(whereClauses, "document_no = ?")
	args = append(args, t.No)

	whereClause := "1=1"
	if len(whereClauses) > 0 {
		whereClause = strings.Join(whereClauses, " AND ")
	}

	query := fmt.Sprintf(`SELECT COALESCE(SUM(amount), 0) FROM "%s" WHERE %s`, tableName, whereClause)

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))

	var sumStr string
	err := t.db.QueryRow(query, args...).Scan(&sumStr)
	if err != nil {
		fmt.Printf("Error: Failed to calculate sum for amount: %v\n", err)
		return types.ZeroDecimal()
	}

	sum, _ := types.NewDecimalFromString(sumStr)
	return sum
}

